arguments.command:
node --input-type=module -e "
import { writeFileSync } from 'node:fs';
import { tax } from './tax.mjs';
import { shipping } from './shipping.mjs';
const answer = { tax100: tax(100), shipping2: shipping(2) };
writeFileSync('answer.json', JSON.stringify(answer, null, 2) + '\n');
console.log('wrote', JSON.stringify(answer));
" && cat answer.json

node test.mjs; echo "TEST_EXIT=$?"; node --input-type=module -e "
import fs from 'node:fs';
const a = JSON.parse(fs.readFileSync('answer.json','utf8'));
const ok = typeof a.tax100 === 'number' && typeof a.shipping2 === 'number' && a.tax100 === 20 && a.shipping2 === 7 && Object.keys(a).length === 2;
console.log('answer.json =>', JSON.stringify(a));
console.log('types =>', typeof a.tax100, typeof a.shipping2);
console.log('CHECK', ok ? 'PASS' : 'FAIL');
process.exit(ok ? 0 : 1);
"; echo "ANSWER_EXIT=$?"; echo '--- independence ---'; grep -n "import" tax.mjs shipping.mjs; echo "GREP_EXIT=$?"

